Algorithm DiaSemana
  Define dia As Integer <- 6;
  Switch dia Do
    1, 2, 3, 4, 5:
      Write "Hay clase";
    6, 7:
      Write "Fin de semana";
    Otherwise:
      Write "Ese día no existe";
  EndSwitch
EndAlgorithm

Algorithm Repetida
  Define n As Integer <- 1;
  Switch n Do
    1:
      Write "uno";
    1:
      Write "otra vez uno";
  EndSwitch
EndAlgorithm
